//! Anything a ray can hit, and the record of where it hit.

use crate::aabb::Aabb;
use crate::ray::Ray;
use crate::vec3::Vec3;

/// Where a ray hit a surface: the distance along the ray, the point, the normal against the
/// ray, the face side and the texture coordinates.
#[derive(Clone, Copy, Debug)]
pub struct HitRecord {
    pub t: f64,
    #[allow(dead_code)]
    pub point: Vec3,
    pub normal: Vec3,
    // Read by the tests only.
    #[allow(dead_code)]
    pub front_face: bool,
    #[allow(dead_code)]
    pub u: f64,
    #[allow(dead_code)]
    pub v: f64,
}

impl HitRecord {
    /// Return a hit at distance `t` and `point`, with texture coordinates `(u, v)` and a normal
    /// facing `ray`. `outward_normal` is unit length and points away from the surface.
    pub fn new(t: f64, point: Vec3, u: f64, v: f64, ray: &Ray, outward_normal: Vec3) -> Self {
        let front_face = ray.direction.dot(outward_normal) < 0.0;
        let normal = if front_face {
            outward_normal
        } else {
            -outward_normal
        };
        HitRecord {
            t,
            point,
            normal,
            front_face,
            u,
            v,
        }
    }
}

pub trait Hittable {
    /// The nearest hit with `t` in `t_min..t_max`, if any.
    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord>;

    /// The box used to skip objects the ray misses, or `None` when every ray must test the object.
    fn bounding_box(&self) -> Option<Aabb>;
}

/// A scene: every object, hit in order of distance.
#[derive(Default)]
pub struct HittableList {
    pub objects: Vec<Box<dyn Hittable>>,
}

impl HittableList {
    pub fn add(&mut self, object: Box<dyn Hittable>) {
        self.objects.push(object);
    }
}

impl Hittable for HittableList {
    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
        let mut nearest: Option<HitRecord> = None;
        for object in &self.objects {
            let limit = nearest.as_ref().map_or(t_max, |hit| hit.t);
            if let Some(bounding_box) = object.bounding_box() {
                if !bounding_box.hit(ray, t_min, limit) {
                    continue;
                }
            }
            if let Some(hit) = object.hit(ray, t_min, limit) {
                nearest = Some(hit);
            }
        }
        nearest
    }

    fn bounding_box(&self) -> Option<Aabb> {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;
    use std::rc::Rc;

    /// A shape that counts its tests and never reports a hit.
    struct Probe {
        bounding_box: Aabb,
        calls: Rc<Cell<usize>>,
    }

    impl Hittable for Probe {
        fn hit(&self, _ray: &Ray, _t_min: f64, _t_max: f64) -> Option<HitRecord> {
            self.calls.set(self.calls.get() + 1);
            None
        }

        fn bounding_box(&self) -> Option<Aabb> {
            Some(self.bounding_box)
        }
    }

    #[test]
    fn the_list_skips_an_object_when_the_ray_misses_its_box() {
        let calls = Rc::new(Cell::new(0));
        let mut world = HittableList::default();
        world.add(Box::new(Probe {
            bounding_box: Aabb::new(Vec3::new(5.0, 5.0, -3.0), Vec3::new(6.0, 6.0, -2.0)),
            calls: Rc::clone(&calls),
        }));
        let beside = Ray::new(Vec3::new(0.0, 0.0, 0.0), Vec3::new(0.0, 0.0, -1.0));
        assert!(world.hit(&beside, 0.001, f64::INFINITY).is_none());
        assert_eq!(calls.get(), 0);
        let through = Ray::new(Vec3::new(5.5, 5.5, 0.0), Vec3::new(0.0, 0.0, -1.0));
        assert!(world.hit(&through, 0.001, f64::INFINITY).is_none());
        assert_eq!(calls.get(), 1);
    }
}
//! Axis-aligned bounding boxes.

use crate::ray::Ray;
use crate::vec3::Vec3;

/// An axis-aligned box whose sides lie along the coordinate axes.
#[derive(Clone, Copy, Debug)]
pub struct Aabb {
    pub min: Vec3,
    pub max: Vec3,
}

impl Aabb {
    /// Create the box whose corners are `min` and `max`.
    /// `min` is the lower corner in every axis.
    pub fn new(min: Vec3, max: Vec3) -> Self {
        Aabb { min, max }
    }

    /// Return whether the ray meets the box with `t` in `t_min..t_max`.
    pub fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> bool {
        let mut t_near = t_min;
        let mut t_far = t_max;
        let slabs = [
            (self.min.x, self.max.x, ray.origin.x, ray.direction.x),
            (self.min.y, self.max.y, ray.origin.y, ray.direction.y),
            (self.min.z, self.max.z, ray.origin.z, ray.direction.z),
        ];
        for (min, max, origin, direction) in slabs {
            let inverse = 1.0 / direction;
            // A zero `direction` gives infinite bounds, and a bound that is NaN because the
            // origin lies exactly on that face is ignored by `max` and `min`.
            let mut t0 = (min - origin) * inverse;
            let mut t1 = (max - origin) * inverse;
            if t0 > t1 {
                std::mem::swap(&mut t0, &mut t1);
            }
            t_near = t_near.max(t0);
            t_far = t_far.min(t1);
            if t_near > t_far {
                return false;
            }
        }
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_ray_through_the_box_hits_it_and_a_ray_beside_it_misses() {
        let aabb = Aabb::new(Vec3::new(-1.0, -1.0, -1.0), Vec3::new(1.0, 1.0, 1.0));
        let through = Ray::new(Vec3::new(0.0, 0.0, 0.0), Vec3::new(0.0, 0.0, -1.0));
        assert!(aabb.hit(&through, 0.001, f64::INFINITY));
        let beside = Ray::new(Vec3::new(2.0, 0.0, 0.0), Vec3::new(0.0, 0.0, -1.0));
        assert!(!aabb.hit(&beside, 0.001, f64::INFINITY));
    }
}
//! Planes.

use crate::aabb::Aabb;
use crate::hittable::{HitRecord, Hittable};
use crate::ray::Ray;
use crate::vec3::Vec3;

/// An infinite plane through a point, with a unit normal.
pub struct Plane {
    pub point: Vec3,
    pub normal: Vec3,
}

impl Plane {
    /// Create a plane through `point` with `normal`.
    /// `normal` is unit length.
    pub fn new(point: Vec3, normal: Vec3) -> Self {
        Plane { point, normal }
    }
}

impl Hittable for Plane {
    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
        let denominator = ray.direction.dot(self.normal);
        if denominator == 0.0 {
            return None;
        }
        let t = (self.point - ray.origin).dot(self.normal) / denominator;
        if t <= t_min || t >= t_max {
            return None;
        }
        let point = ray.at(t);
        let (u_axis, v_axis) = plane_axes(self.normal);
        let u = point.dot(u_axis).rem_euclid(1.0);
        let v = point.dot(v_axis).rem_euclid(1.0);
        Some(HitRecord::new(t, point, u, v, ray, self.normal))
    }

    fn bounding_box(&self) -> Option<Aabb> {
        None
    }
}

/// Two unit axes in the plane, perpendicular to each other and to `normal`.
fn plane_axes(normal: Vec3) -> (Vec3, Vec3) {
    // The helper is the world axis least aligned with the normal, so the two are never
    // parallel and the cross product is never zero.
    let helper = if normal.x.abs() <= normal.y.abs() && normal.x.abs() <= normal.z.abs() {
        Vec3::new(1.0, 0.0, 0.0)
    } else if normal.y.abs() <= normal.z.abs() {
        Vec3::new(0.0, 1.0, 0.0)
    } else {
        Vec3::new(0.0, 0.0, 1.0)
    };
    let u_axis = normal.cross(helper).unit();
    (u_axis, normal.cross(u_axis))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_ray_hits_the_plane_with_wrapped_texture_coordinates() {
        let plane = Plane::new(Vec3::new(0.0, 0.0, -2.0), Vec3::new(0.0, 0.0, 1.0));
        let ray = Ray::new(Vec3::new(0.25, 0.5, 0.0), Vec3::new(0.0, 0.0, -1.0));
        let hit = plane.hit(&ray, 0.001, f64::INFINITY).expect("the ray hits");
        assert_eq!(hit.t, 2.0);
        assert_eq!(hit.point, Vec3::new(0.25, 0.5, -2.0));
        assert!(hit.front_face);
        assert_eq!(hit.normal, Vec3::new(0.0, 0.0, 1.0));
        assert_eq!(hit.u, 0.5);
        assert_eq!(hit.v, 0.75);
    }
}
//! Triangles.

use crate::aabb::Aabb;
use crate::hittable::{HitRecord, Hittable};
use crate::ray::Ray;
use crate::vec3::Vec3;

/// A triangle from three vertices, in the order that sets its outward normal.
pub struct Triangle {
    pub a: Vec3,
    pub b: Vec3,
    pub c: Vec3,
}

impl Triangle {
    /// Create a triangle with vertices `a`, `b` and `c`.
    /// The vertex order sets the outward normal that decides the face side.
    pub fn new(a: Vec3, b: Vec3, c: Vec3) -> Self {
        Triangle { a, b, c }
    }
}

impl Hittable for Triangle {
    fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
        let edge1 = self.b - self.a;
        let edge2 = self.c - self.a;
        let pvec = ray.direction.cross(edge2);
        let determinant = edge1.dot(pvec);
        // A determinant near zero means the ray runs parallel to the triangle's plane.
        if determinant.abs() < 1e-8 {
            return None;
        }
        let inverse = 1.0 / determinant;
        let tvec = ray.origin - self.a;
        let u = tvec.dot(pvec) * inverse;
        if !(0.0..=1.0).contains(&u) {
            return None;
        }
        let qvec = tvec.cross(edge1);
        let v = ray.direction.dot(qvec) * inverse;
        if v < 0.0 || u + v > 1.0 {
            return None;
        }
        let t = edge2.dot(qvec) * inverse;
        if t <= t_min || t >= t_max {
            return None;
        }
        let point = ray.at(t);
        let outward_normal = edge1.cross(edge2).unit();
        Some(HitRecord::new(t, point, u, v, ray, outward_normal))
    }

    fn bounding_box(&self) -> Option<Aabb> {
        Some(Aabb::new(
            Vec3::new(
                self.a.x.min(self.b.x).min(self.c.x),
                self.a.y.min(self.b.y).min(self.c.y),
                self.a.z.min(self.b.z).min(self.c.z),
            ),
            Vec3::new(
                self.a.x.max(self.b.x).max(self.c.x),
                self.a.y.max(self.b.y).max(self.c.y),
                self.a.z.max(self.b.z).max(self.c.z),
            ),
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_ray_hits_the_triangle_with_barycentric_texture_coordinates() {
        let triangle = Triangle::new(
            Vec3::new(0.0, 0.0, -2.0),
            Vec3::new(1.0, 0.0, -2.0),
            Vec3::new(0.0, 1.0, -2.0),
        );
        let ray = Ray::new(Vec3::new(0.25, 0.25, 0.0), Vec3::new(0.0, 0.0, -1.0));
        let hit = triangle
            .hit(&ray, 0.001, f64::INFINITY)
            .expect("the ray hits");
        assert_eq!(hit.t, 2.0);
        assert_eq!(hit.point, Vec3::new(0.25, 0.25, -2.0));
        assert!(hit.front_face);
        assert_eq!(hit.normal, Vec3::new(0.0, 0.0, 1.0));
        assert_eq!(hit.u, 0.25);
        assert_eq!(hit.v, 0.25);
    }

    #[test]
    fn a_ray_beside_the_triangle_misses() {
        let triangle = Triangle::new(
            Vec3::new(0.0, 0.0, -2.0),
            Vec3::new(1.0, 0.0, -2.0),
            Vec3::new(0.0, 1.0, -2.0),
        );
        let ray = Ray::new(Vec3::new(2.0, 2.0, 0.0), Vec3::new(0.0, 0.0, -1.0));
        assert!(triangle.hit(&ray, 0.001, f64::INFINITY).is_none());
    }
}

//! Render a fixed scene and write it to standard output as a PPM image.

mod aabb;
mod camera;
mod hittable;
#[allow(dead_code)]
mod plane;
mod ray;
#[allow(dead_code)]
mod rng;
mod sphere;
mod triangle;
mod vec3;

use std::io::{self, Write};

use camera::Camera;
use hittable::{Hittable, HittableList};
use ray::Ray;
use sphere::Sphere;
use triangle::Triangle;
use vec3::{Colour, Vec3};

const WIDTH: usize = 200;
const HEIGHT: usize = 100;

/// The colour seen along a ray: the surface normal where it hits, the sky gradient otherwise.
fn ray_colour(ray: &Ray, world: &dyn Hittable) -> Colour {
    if let Some(hit) = world.hit(ray, 0.001, f64::INFINITY) {
        return (hit.normal + Vec3::new(1.0, 1.0, 1.0)) * 0.5;
    }
    let t = 0.5 * (ray.direction.unit().y + 1.0);
    Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
}

fn scene() -> HittableList {
    let mut world = HittableList::default();
    world.add(Box::new(Sphere::new(Vec3::new(0.0, 0.0, -1.0), 0.5)));
    world.add(Box::new(Sphere::new(Vec3::new(0.0, -100.5, -1.0), 100.0)));
    world.add(Box::new(Triangle::new(
        Vec3::new(-3.5, 0.0, -2.0),
        Vec3::new(-1.5, 0.0, -2.0),
        Vec3::new(-2.5, 1.5, -2.0),
    )));
    world
}

/// Every pixel's colour, row by row from the top.
fn render(width: usize, height: usize) -> Vec<Colour> {
    let world = scene();
    let camera = Camera::new(width as f64 / height as f64);
    let mut pixels = Vec::with_capacity(width * height);
    for row in (0..height).rev() {
        for column in 0..width {
            let u = column as f64 / (width - 1) as f64;
            let v = row as f64 / (height - 1) as f64;
            pixels.push(ray_colour(&camera.ray(u, v), &world));
        }
    }
    pixels
}

fn to_byte(channel: f64) -> u8 {
    (255.999 * channel.clamp(0.0, 1.0)) as u8
}

fn write_ppm(
    out: &mut impl Write,
    width: usize,
    height: usize,
    pixels: &[Colour],
) -> io::Result<()> {
    writeln!(out, "P3\n{width} {height}\n255")?;
    for pixel in pixels {
        writeln!(
            out,
            "{} {} {}",
            to_byte(pixel.x),
            to_byte(pixel.y),
            to_byte(pixel.z)
        )?;
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let pixels = render(WIDTH, HEIGHT);
    write_ppm(&mut io::stdout().lock(), WIDTH, HEIGHT, &pixels)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_center_pixel_shows_the_sphere_facing_the_camera() {
        let pixels = render(WIDTH, HEIGHT);
        let center = pixels[(HEIGHT / 2) * WIDTH + WIDTH / 2];
        assert!(center.z > 0.9, "the normal faces the camera: {center:?}");
    }

    #[test]
    fn the_top_row_is_sky() {
        let pixels = render(WIDTH, HEIGHT);
        assert!(pixels[0].z > pixels[0].x, "the sky is bluer than it is red");
    }
}
